<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop</title>
<style>
  :root {
    --bg: #171421;
    --panel: #241f2f;
    --panel-light: #30283e;
    --text: #f3eef7;
    --muted: #b9adc4;
    --accent: #e95420;
    --accent-light: #ff7448;
    --border: rgba(255,255,255,.13);
  }

  * { box-sizing: border-box; }
  html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }
  body {
    color: var(--text);
    font-family: "Segoe UI", Arial, sans-serif;
    background: #171421;
  }

  #desktop {
    width: 100vw;
    height: 100vh;
    position: relative;
    overflow: hidden;
    background:
      radial-gradient(circle at 72% 30%, rgba(118,42,91,.34), transparent 27%),
      radial-gradient(circle at 25% 75%, rgba(42,55,115,.38), transparent 30%),
      linear-gradient(135deg, #161522 0%, #251735 48%, #121c35 100%);
  }

  #desktop::before, #desktop::after {
    content: "";
    position: absolute;
    pointer-events: none;
    border-radius: 50%;
    filter: blur(2px);
  }
  #desktop::before {
    width: 75vw; height: 75vw;
    left: -30vw; bottom: -48vw;
    border: 2px solid rgba(231,84,32,.22);
    box-shadow: 0 0 0 42px rgba(231,84,32,.09), 0 0 0 84px rgba(231,84,32,.045);
  }
  #desktop::after {
    width: 45vw; height: 45vw;
    right: -20vw; top: -25vw;
    border: 1px solid rgba(113,111,255,.22);
    box-shadow: 0 0 0 34px rgba(113,111,255,.08);
  }

  #topbar {
    height: 34px;
    position: absolute;
    z-index: 20;
    inset: 0 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 15px;
    background: rgba(15,13,22,.78);
    border-bottom: 1px solid rgba(255,255,255,.07);
    font-size: 13px;
  }
  .top-left, .top-right { display: flex; align-items: center; gap: 17px; }
  .ubuntu-mark { color: var(--accent-light); font-size: 20px; line-height: 0; }
  .top-title { font-weight: 600; }
  .top-muted { color: var(--muted); }

  #taskbar {
    position: absolute;
    z-index: 30;
    left: 50%;
    bottom: 13px;
    transform: translateX(-50%);
    display: flex;
    gap: 8px;
    padding: 8px 10px;
    border: 1px solid var(--border);
    border-radius: 15px;
    background: rgba(27,23,36,.85);
    box-shadow: 0 12px 35px rgba(0,0,0,.35);
    backdrop-filter: blur(16px);
  }

  .launcher {
    width: 47px;
    height: 47px;
    border: 0;
    border-radius: 11px;
    color: white;
    background: transparent;
    cursor: pointer;
    font-size: 23px;
    transition: .18s ease;
  }
  .launcher:hover { background: rgba(255,255,255,.12); transform: translateY(-3px); }
  .launcher:active { transform: translateY(0); }
  .launcher-label { display: block; font-size: 8px; margin-top: 1px; color: var(--muted); }
  .files-icon { color: #f4c542; }
  .note-icon { color: #78c7f5; }

  .window {
    position: absolute;
    z-index: 10;
    display: none;
    width: min(650px, calc(100vw - 38px));
    height: min(455px, calc(100vh - 105px));
    min-width: 360px;
    min-height: 240px;
    border: 1px solid rgba(255,255,255,.18);
    border-radius: 10px;
    overflow: hidden;
    background: rgba(36,31,47,.96);
    box-shadow: 0 20px 65px rgba(0,0,0,.58);
    backdrop-filter: blur(18px);
  }
  #files-window { left: 9vw; top: 13vh; }
  #notepad-window { left: 28vw; top: 18vh; }

  .window.active { display: flex; flex-direction: column; }
  .titlebar {
    height: 41px;
    flex: 0 0 41px;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 0 12px;
    background: linear-gradient(#393044, #30283c);
    border-bottom: 1px solid var(--border);
    cursor: grab;
    user-select: none;
  }
  .titlebar:active { cursor: grabbing; }
  .app-symbol { color: var(--accent-light); font-size: 18px; }
  .window-title { flex: 1; font-size: 13px; font-weight: 600; }
  .win-close {
    width: 23px; height: 23px; border: 0; border-radius: 50%;
    color: #fff; background: #e95420; cursor: pointer; font-size: 16px;
    line-height: 20px;
  }
  .win-close:hover { background: #ff7650; }

  .files-toolbar {
    display: flex; align-items: center; gap: 9px; padding: 10px 12px;
    border-bottom: 1px solid var(--border);
  }
  .tool-button {
    color: var(--text); background: var(--panel-light); border: 1px solid var(--border);
    border-radius: 5px; padding: 6px 10px; cursor: pointer;
  }
  .tool-button:hover { background: #403550; }
  #files-path {
    flex: 1; min-width: 0; padding: 7px 10px; border-radius: 5px;
    color: #f5d4c9; background: #1c1826; border: 1px solid var(--border);
    font-family: Consolas, monospace; font-size: 12px;
  }
  #files-list {
    flex: 1; overflow: auto; padding: 15px;
    display: grid; grid-template-columns: repeat(auto-fill, minmax(115px, 1fr));
    align-content: start; gap: 10px;
  }
  .fs-item {
    min-height: 75px; padding: 12px 8px; display: flex; flex-direction: column;
    justify-content: center; align-items: center; gap: 7px; border: 1px solid transparent;
    border-radius: 7px; cursor: default; font-size: 12px; text-align: center;
    word-break: break-word;
  }
  .fs-item:hover { background: rgba(255,255,255,.09); border-color: var(--border); }
  .fs-item.folder { cursor: pointer; }
  .fs-icon { font-size: 27px; color: #efc24d; }
  .fs-item.file .fs-icon { color: #9fc7de; }

  #notepad-content { flex: 1; display: flex; flex-direction: column; min-height: 0; }
  #tabs {
    display: flex; align-items: center; gap: 3px; padding: 7px 8px 0;
    overflow-x: auto; background: #211c2c; border-bottom: 1px solid var(--border);
  }
  .tab {
    max-width: 150px; min-width: 75px; padding: 8px 13px; overflow: hidden;
    white-space: nowrap; text-overflow: ellipsis; color: var(--muted);
    background: #2c2638; border: 1px solid transparent; border-bottom: 0;
    border-radius: 6px 6px 0 0; cursor: pointer; font-size: 12px;
  }
  .tab.active { color: white; background: #42374e; border-color: var(--border); }
  #new-tab {
    flex: 0 0 auto; margin: 0 4px 6px; width: 27px; height: 27px; border: 0;
    border-radius: 5px; color: white; background: transparent; cursor: pointer; font-size: 20px;
  }
  #new-tab:hover { background: rgba(255,255,255,.12); }
  #editor {
    flex: 1; width: 100%; min-height: 0; resize: none; border: 0; outline: 0;
    padding: 18px; color: #f4eff7; background: rgba(25,21,33,.72);
    font: 14px/1.6 Consolas, "Courier New", monospace;
  }
  .statusbar { padding: 5px 12px; color: var(--muted); background: #211c2c; font-size: 11px; }
</style>
</head>
<body>
<div id="desktop">
  <div id="topbar">
    <div class="top-left"><span class="ubuntu-mark">●</span><span class="top-title">Activities</span><span class="top-muted">Desktop</span></div>
    <div class="top-right"><span class="top-muted">⌁</span><span class="top-muted">▮▮</span><span id="clock"></span><span>▾</span></div>
  </div>

  <section id="files-window" class="window" aria-label="Files">
    <div class="titlebar">
      <span class="app-symbol">▰</span><span class="window-title">Files</span><button class="win-close" aria-label="Close">×</button>
    </div>
    <div class="files-toolbar">
      <button id="files-up" class="tool-button" title="Parent folder">↑</button>
      <div id="files-path">/</div>
    </div>
    <div id="files-list" aria-label="Filesystem listing"></div>
  </section>

  <section id="notepad-window" class="window" aria-label="Notepad">
    <div class="titlebar">
      <span class="app-symbol">✎</span><span class="window-title">Notepad</span><button class="win-close" aria-label="Close">×</button>
    </div>
    <div id="notepad-content">
      <div id="tabs"><button id="new-tab" title="New tab">+</button></div>
      <textarea id="editor" spellcheck="false" aria-label="Editor"></textarea>
      <div class="statusbar" id="note-status">Ready</div>
    </div>
  </section>

  <nav id="taskbar" aria-label="Application dock">
    <button id="open-files" class="launcher" title="Open Files">▰<span class="launcher-label">Files</span></button>
    <button id="open-notepad" class="launcher" title="Open Notepad">✎<span class="launcher-label">Notepad</span></button>
  </nav>
</div>

<script>
(function () {
  const filesWindow = document.getElementById("files-window");
  const noteWindow = document.getElementById("notepad-window");
  const desktop = document.getElementById("desktop");

  function show(win) {
    win.classList.add("active");
    document.querySelectorAll(".window").forEach(w => w.style.zIndex = "10");
    win.style.zIndex = "15";
  }
  document.getElementById("open-files").onclick = () => show(filesWindow);
  document.getElementById("open-notepad").onclick = () => { show(noteWindow); renderTabs(); };
  document.querySelectorAll(".win-close").forEach(btn => btn.onclick = e => e.target.closest(".window").classList.remove("active"));
  document.querySelectorAll(".window").forEach(win => win.addEventListener("mousedown", () => win.style.zIndex = "15"));

  const fs = {
    "/": { bin: "folder", etc: "folder", home: "folder", usr: "folder", var: "folder" },
    "/bin": { bash: "file", cat: "file", ls: "file", mkdir: "file", nano: "file" },
    "/etc": { "hostname": "file", "hosts": "file", "os-release": "file", "network": "folder" },
    "/home": { user: "folder" },
    "/home/user": { Documents: "folder", Downloads: "folder", Pictures: "folder", Music: "folder", "welcome.txt": "file" },
    "/home/user/Documents": { "notes.txt": "file", "project.md": "file" },
    "/home/user/Downloads": { "ubuntu-wallpaper.png": "file", "archive.zip": "file" },
    "/home/user/Pictures": { "sunset.jpg": "file" },
    "/usr": { bin: "folder", lib: "folder", share: "folder", local: "folder" },
    "/var": { cache: "folder", log: "folder", tmp: "folder" },
    "/etc/network": { interfaces: "file" }
  };
  let currentPath = "/";
  const pathEl = document.getElementById("files-path");
  const listEl = document.getElementById("files-list");

  function renderFiles() {
    pathEl.textContent = currentPath;
    listEl.innerHTML = "";
    const entries = fs[currentPath] || {};
    Object.keys(entries).sort((a,b) => entries[a] === entries[b] ? a.localeCompare(b) : entries[a] === "folder" ? -1 : 1)
      .forEach(name => {
        const type = entries[name], item = document.createElement("div");
        item.className = "fs-item " + type;
        item.innerHTML = '<span class="fs-icon">' + (type === "folder" ? "▰" : "▤") + '</span><span>' + name + '</span>';
        if (type === "folder") item.ondblclick = () => {
          currentPath = currentPath === "/" ? "/" + name : currentPath + "/" + name;
          renderFiles();
        };
        listEl.appendChild(item);
      });
  }
  document.getElementById("files-up").onclick = () => {
    if (currentPath !== "/") {
      const parts = currentPath.split("/").filter(Boolean);
      parts.pop();
      currentPath = parts.length ? "/" + parts.join("/") : "/";
      renderFiles();
    }
  };
  renderFiles();

  const storageKey = "ubuntu-notepad-tabs-v1";
  let tabs;
  try { tabs = JSON.parse(localStorage.getItem(storageKey)) || null; } catch (_) { tabs = null; }
  if (!Array.isArray(tabs) || !tabs.length) tabs = [{ name: "Untitled", content: "" }];
  let activeTab = 0;
  const tabsEl = document.getElementById("tabs"), editor = document.getElementById("editor"), status = document.getElementById("note-status");

  function saveTabs() { localStorage.setItem(storageKey, JSON.stringify(tabs)); }
  function renderTabs() {
    tabsEl.querySelectorAll(".tab").forEach(t => t.remove());
    tabs.forEach((tab, i) => {
      const el = document.createElement("button");
      el.className = "tab" + (i === activeTab ? " active" : "");
      el.textContent = tab.name || "Untitled";
      el.onclick = () => { tabs[activeTab].content = editor.value; activeTab = i; renderTabs(); };
      tabsEl.insertBefore(el, document.getElementById("new-tab"));
    });
    editor.value = tabs[activeTab].content;
    status.textContent = tabs.length + (tabs.length === 1 ? " tab" : " tabs") + " • " + editor.value.length + " characters";
  }
  editor.oninput = () => {
    tabs[activeTab].content = editor.value;
    saveTabs();
    status.textContent = tabs.length + (tabs.length === 1 ? " tab" : " tabs") + " • " + editor.value.length + " characters";
  };
  document.getElementById("new-tab").onclick = () => {
    tabs[activeTab].content = editor.value;
    tabs.push({ name: "Untitled " + (tabs.length + 1), content: "" });
    activeTab = tabs.length - 1;
    saveTabs(); renderTabs(); editor.focus();
  };
  renderTabs();

  document.querySelectorAll(".titlebar").forEach(bar => {
    bar.addEventListener("mousedown", e => {
      if (e.target.closest(".win-close")) return;
      const win = bar.closest(".window"), startX = e.clientX, startY = e.clientY;
      const startLeft = win.offsetLeft, startTop = win.offsetTop;
      const move = ev => {
        win.style.left = Math.max(0, Math.min(window.innerWidth - 80, startLeft + ev.clientX - startX)) + "px";
        win.style.top = Math.max(34, Math.min(window.innerHeight - 80, startTop + ev.clientY - startY)) + "px";
      };
      const stop = () => { document.removeEventListener("mousemove", move); document.removeEventListener("mouseup", stop); };
      document.addEventListener("mousemove", move); document.addEventListener("mouseup", stop);
    });
  });

  function updateClock() {
    document.getElementById("clock").textContent = new Date().toLocaleTimeString([], {hour: "2-digit", minute: "2-digit"});
  }
  updateClock(); setInterval(updateClock, 30000);
})();
</script>
</body>
</html>
